// Core Game Types for AI Alignment Game
// This file now imports from focused type modules and re-exports for backward compatibility

// Import all types from new focused modules
export type {
  ScenarioMode,
  ScenarioParameters,
  ConfigurationSettings,
  RNGFunction
} from './config';

export type {
  GameEvent,
  GameAction,
  AgentType
} from './events';

export type {
  ExtinctionType,
