  // console.log(`\n🔍 SPIRAL DIAGNOSTICS (${timeDisplay})`);
  // console.log(`================================================================================`);

  // Count active spirals
  const activeSpiralNames = getActiveSpiralNames(spirals);

  // Aggregate spiral status via eventAggregator (method doesn't exist yet)
